import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"設施服","description":"設施服的相關介紹。","frontmatter":{"title":"設施服","description":"設施服的相關介紹。"},"headers":[],"relativePath":"server/mh/index.md","filePath":"server/mh.md"}'),t={name:"server/mh/index.md"};function o(h,l,d,s,u,n){return a(),i("div",null,[...l[0]||(l[0]=[r('<h1 id="設施服-mh" tabindex="-1">設施服 mh <a class="header-anchor" href="#設施服-mh" aria-label="Permalink to &quot;設施服 mh&quot;">​</a></h1><p><font size="4" color="green"><b>建造紅石機關/生怪塔/物資塔/大型紅石設備</b></font></p><ul><li>如果有需要蓋上述很吃效能的東西，請在此伺服建造</li><li>不是很建議蓋家居住在此伺服，建議前往<a href="/server/sv/">主伺服(sv)</a></li><li>若需採集資源，建議前往<a href="/server/res/">資源服(res)</a></li></ul><h2 id="現有分流" tabindex="-1">現有分流 <a class="header-anchor" href="#現有分流" aria-label="Permalink to &quot;現有分流&quot;">​</a></h2><ul><li>設一(mh1)</li><li>設二(mh2)</li><li>設三(mh3) <ul><li><a href="/donate/">贊助玩家</a>或被贊助玩家邀請才可進入</li></ul></li></ul><h2 id="前往方式" tabindex="-1">前往方式 <a class="header-anchor" href="#前往方式" aria-label="Permalink to &quot;前往方式&quot;">​</a></h2><ul><li>從<a href="/server/Lobby/">大廳服(Lobby)</a>的傳送門前往</li><li>使用<code>/home</code>或<code>/back</code>傳送到位於該分流的紀錄點</li></ul><h2 id="分流設定" tabindex="-1">分流設定 <a class="header-anchor" href="#分流設定" aria-label="Permalink to &quot;分流設定&quot;">​</a></h2><h3 id="基本設定" tabindex="-1">基本設定 <a class="header-anchor" href="#基本設定" aria-label="Permalink to &quot;基本設定&quot;">​</a></h3><ul><li>地圖防爆、防燒</li><li>防噴裝、死亡扣除部分經驗 <ul><li>死亡時扣除等級的1/10(最少1等，最多10等) <ul><li>玩家經驗等級在1等以下時不扣除經驗</li><li>被玩家擊殺(PVP)時只扣除1等</li></ul></li></ul></li></ul><h3 id="特殊設定" tabindex="-1">特殊設定 <a class="header-anchor" href="#特殊設定" aria-label="Permalink to &quot;特殊設定&quot;">​</a></h3><ul><li><font color="red"><b>有指定掉落物定時清除機制</b></font><ul><li><b>指定掉落物：</b>竹子、甘蔗、西瓜、南瓜、海帶、仙人掌</li></ul></li><li>終界使者不會撿起方塊</li><li>綿羊不會受到雷擊傷害 <ul><li>仍然建議玩家在羊毛機附近設置避雷針</li></ul></li><li>部分生物有繁殖限制 <ul><li>牛、豬：10格內小於15隻才可繁殖</li><li>悅靈：10格內小於5隻才可繁殖</li></ul></li><li>無法繁殖綿羊 <ul><li>可使用<a href="/feature/sp_tool/">綿羊卷軸</a>提升單隻綿羊的產量</li></ul></li><li>無法召喚終界龍 <ul><li>請前往<a href="/server/res/">資源服(res)</a></li></ul></li><li>不會生成夜魅 <ul><li>請前往<a href="/server/res/">資源服(res)</a></li></ul></li><li>不會生成任何魚類 <ul><li>請前往<a href="/server/res/">資源服(res)</a></li></ul></li><li>伏聆觸媒蔓延範圍限制為三軸正負6格內(13x13x13) <ul><li>請前往<a href="/server/res/">資源服(res)</a></li></ul></li><li>無法挖掘地獄的遠古遺骸 <ul><li>請前往<a href="/server/res/">資源服(res)</a></li><li><font color="red"><b>請不要在地獄放遠古遺骸，挖掘時會被系統清除</b></font></li></ul></li><li>原木剝皮/銅塊除蠟需使用有絲綢之觸附魔的鑽石/獄髓斧 <ul><li><a href="/server/res/">資源服(res)</a>無此限制</li><li>單純對銅塊除鏽可使用任意的斧頭</li></ul></li></ul><h3 id="邊界大小" tabindex="-1">邊界大小 <a class="header-anchor" href="#邊界大小" aria-label="Permalink to &quot;邊界大小&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分流</th><th>主世界</th><th>地獄</th><th>終界</th></tr></thead><tbody><tr><td>設一(mh1)</td><td>+-15000</td><td>+-10000</td><td>+-20000</td></tr><tr><td>設二(mh2)</td><td>+-13000</td><td>+-10000</td><td>+-12000</td></tr><tr><td>設三(mh3)</td><td>+-15000</td><td>+-8000</td><td>+-8000</td></tr></tbody></table><h2 id="切換世界-分流方式" tabindex="-1">切換世界/分流方式 <a class="header-anchor" href="#切換世界-分流方式" aria-label="Permalink to &quot;切換世界/分流方式&quot;">​</a></h2><h3 id="切換世界" tabindex="-1">切換世界 <a class="header-anchor" href="#切換世界" aria-label="Permalink to &quot;切換世界&quot;">​</a></h3><ul><li>前往地獄請自行找地方蓋地獄門</li><li>前往終界請輸入<code>/spawn</code>回到分流重生點後由傳送門前往</li></ul><h3 id="切換分流" tabindex="-1">切換分流 <a class="header-anchor" href="#切換分流" aria-label="Permalink to &quot;切換分流&quot;">​</a></h3><ul><li>前往<a href="/server/Lobby/">大廳服(Lobby)</a><ul><li>輸入<code>bs</code>後點選指南針前往</li></ul></li><li>前往對應的<a href="/server/sv/">主伺服(sv)</a>(主一/設一 主二/設二 主三/設三) <ul><li>輸入<code>/spawn</code>回到分流重生點後由傳送門前往</li></ul></li><li>前往其他分流 商店街 美術公園 <ul><li>請切換至<a href="/server/Lobby/">大廳服(Lobby)</a>後由各分流傳送門前往</li></ul></li></ul>',19)])])}const f=e(t,[["render",o]]);export{b as __pageData,f as default};
